import sys

def main():
    s = sys.stdin.readline().strip()
    pac = [i for i, c in enumerate(s) if c == 'P']
    stars = [i for i, c in enumerate(s) if c == '*']
    S = len(stars)

    def ok(T):
        j = 0
        for p in pac:
            if j < S and stars[j] < p:
                d = p - stars[j]
                if d > T:
                    return False
                r = p + max(T - 2 * d, (T - d) // 2)
            else:
                r = p + T
            while j < S and stars[j] <= r:
                j += 1
            if j == S:
                return True
        return j == S

    lo, hi = 0, 2 * len(s)
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

