def gen(rng):
    tests = ['P*', '*P', 'P.*', '*.P', '*P*', 'P.....*', '*..*PP*....*P', 'PP**', '*.P.*', '*P*P*', 'P' + '*' * 8, '*' * 8 + 'P']
    def rnd(n, pp, ps):
        while True:
            s = ''.join('P' if x < pp else '*' if x < pp + ps else '.' for x in (rng.random() for _ in range(n)))
            if 'P' in s and '*' in s:
                return s
    for _ in range(60):
        n = rng.randint(2, 14)
        while True:
            s = rnd(n, rng.choice([0.1, 0.2, 0.3]), rng.choice([0.2, 0.4, 0.6]))
            if s.count('P') <= 4 and s.count('*') <= 7:
                break
        tests.append(s)
    N = 100000
    tests.append(rnd(N, 0.1, 0.3))
    tests.append(rnd(N, 0.002, 0.5))
    tests.append('*' * (N // 2) + 'P' + '*' * (N // 2 - 1))
    tests.append('P' + '.' * (N - 2) + '*')
    tests.append(rnd(N, 0.3, 0.3))
    tests.append(('P' + '.' * 40 + '*' * 20 + '.' * 30) * 700)
    return [t if isinstance(t, str) else t for t in tests]

